begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('private','employee_disability_profiles','health fields live separately');
select ok((select relrowsecurity from pg_class where oid='private.employee_disability_profiles'::regclass),'RLS enabled');
select ok(not has_table_privilege('authenticated','private.employee_disability_profiles','SELECT'),'no direct reads');
select ok(not has_table_privilege('authenticated','private.employee_disability_profiles','UPDATE'),'no direct edits');
select ok(not has_table_privilege('anon','private.employee_disability_profiles','SELECT'),'no anonymous reads');
select ok(not has_function_privilege('authenticated','public.private_employee_disability_allowed()','EXECUTE'),'helper not public');
select ok(not has_function_privilege('anon','public.get_employee_disability_profile(uuid)','EXECUTE'),'anonymous RPC denied');
select ok(has_function_privilege('authenticated','public.get_employee_disability_profile(uuid)','EXECUTE'),'authenticated guarded RPC');
select ok(not has_function_privilege('anon','public.set_employee_disability_profile(uuid,integer,text,text,text,text)','EXECUTE'),'anonymous write denied');
select is((select count(*)::int from public.role_capability_grants g join public.roles r on r.id=g.role_id where g.capability_code='employee.disability_view' and r.code in ('operations_manager','promotion_lead')),2,'two authorized roles');
select is((select count(*)::int from public.role_capability_grants g join public.roles r on r.id=g.role_id where g.capability_code='employee.disability_view' and r.code not in ('operations_manager','promotion_lead')),0,'no new other role grants');
select ok(position('private_actual_role_codes' in pg_get_functiondef('public.private_employee_disability_allowed()'::regprocedure))>0,'actual roles checked');
select ok(position('private_effective_role_codes' in pg_get_functiondef('public.private_employee_disability_allowed()'::regprocedure))>0,'simulation cannot increase access');
select ok(position('employee.update' in pg_get_functiondef('public.set_employee_disability_profile(uuid,integer,text,text,text,text)'::regprocedure))>0,'existing edit gate retained');
select ok(position('EMPLOYEE_DISABILITY_CONFLICT' in pg_get_functiondef('public.set_employee_disability_profile(uuid,integer,text,text,text,text)'::regprocedure))>0,'stale writes rejected');
select ok(not public.private_employee_disability_allowed(),'unauthenticated helper denies');
select throws_ok($$select public.get_employee_disability_profile('00000000-0000-0000-0000-000000000000')$$,'42501',null,'unauthenticated direct read rejected');
select throws_ok($$select public.set_employee_disability_profile('00000000-0000-0000-0000-000000000000',0,'yes')$$,'42501',null,'unauthenticated direct write rejected');
select * from finish();
rollback;
